export const envelope = [15, 26, 24];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Map();

  function setBlock(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    grid.set(`${x},${y},${z}`, block);
  }

  function delBlock(x, y, z) {
    grid.delete(`${x},${y},${z}`);
  }

  // --- Theme Palette Resolution ---
  const rawPlank = api.theme.wood.planks || "minecraft:oak_planks";
  const rawLog = api.theme.wood.log || "minecraft:oak_log";
  const rawStripped = api.theme.wood.stripped || "minecraft:stripped_oak_log";
  const rawStairs = api.theme.wood.stairs || "minecraft:oak_stairs";
  const rawSlab = api.theme.wood.slab || "minecraft:oak_slab";
  const rawFence = api.theme.wood.fence || "minecraft:oak_fence";
  const rawTrapdoor = api.theme.wood.trapdoor || "minecraft:oak_trapdoor";

  const plank = rawPlank.split("[")[0];
  const log = rawLog.split("[")[0];
  const stripped = rawStripped.split("[")[0];
  const stair = rawStairs.split("[")[0];
  const slab = rawSlab.split("[")[0];
  const fence = rawFence.split("[")[0];
  const trapdoor = rawTrapdoor.split("[")[0];

  const logX = `${log}[axis=x]`;
  const logY = `${log}[axis=y]`;
  const logZ = `${log}[axis=z]`;
  const stripX = `${stripped}[axis=x]`;
  const stripY = `${stripped}[axis=y]`;
  const stripZ = `${stripped}[axis=z]`;

  function stairState(facing, half = "bottom") {
    return `${stair}[facing=${facing},half=${half}]`;
  }
  function slabState(type = "bottom") {
    return `${slab}[type=${type}]`;
  }
  function trapdoorState(facing = "north", half = "bottom", open = false) {
    return `${trapdoor}[facing=${facing},half=${half},open=${open}]`;
  }

  // =========================================================================
  // 1. WHEELED CHASSIS & ROLLING SLED BASE (Y: 0..3)
  // =========================================================================

  // Sled runners along Z
  for (let z = 3; z <= 21; z++) {
    for (const x of [2, 3, 11, 12]) {
      const ground = api.heightAt(x, z);
      for (let y = Math.min(0, ground); y <= 1; y++) {
        setBlock(x, y, z, logZ);
      }
    }
  }

  // Transverse heavy baulks / axles
  const axleZs = [4, 7, 10, 13, 16, 19];
  for (const az of axleZs) {
    for (let x = 1; x <= 13; x++) {
      setBlock(x, 1, az, logX);
      setBlock(x, 2, az, logX);
    }
  }

  // Platform decking
  for (let z = 4; z <= 20; z++) {
    for (let x = 3; x <= 11; x++) {
      setBlock(x, 2, z, plank);
      if (z === 4 || z === 20 || x === 3 || x === 11) {
        setBlock(x, 3, z, slabState("bottom"));
      }
    }
  }

  // Four Solid Timber Wheel Assemblies
  const wheelHubs = [
    { cx: 1, cz: 7 },
    { cx: 13, cz: 7 },
    { cx: 1, cz: 16 },
    { cx: 13, cz: 16 },
  ];

  for (const { cx, cz } of wheelHubs) {
    const isLeft = cx === 1;
    const facingIn = isLeft ? "east" : "west";
    const facingOut = isLeft ? "west" : "east";

    // Hub and rim
    setBlock(cx, 1, cz, stripX);
    setBlock(cx, 2, cz, slabState("bottom"));
    setBlock(cx, 0, cz, stripX);
    setBlock(cx, 1, cz - 1, stairState("south", "bottom"));
    setBlock(cx, 1, cz + 1, stairState("north", "bottom"));
    setBlock(cx, 2, cz - 1, stairState("north", "top"));
    setBlock(cx, 2, cz + 1, stairState("south", "top"));

    // Inner wheel backing
    const innerX = isLeft ? 2 : 12;
    setBlock(innerX, 1, cz, stripX);
    setBlock(innerX, 2, cz, stairState(facingOut, "top"));

    // Follow terrain under wheel
    const ground = api.heightAt(cx, cz);
    for (let y = ground; y <= 0; y++) {
      setBlock(cx, y, cz, logY);
    }
  }

  // Front Tow Hitch Beam & Rings (toward -Z)
  for (let z = 0; z <= 3; z++) {
    setBlock(7, 2, z, logZ);
    setBlock(6, 2, z, stairState("east", "top"));
    setBlock(8, 2, z, stairState("west", "top"));
  }
  setBlock(7, 3, 0, fence);
  setBlock(7, 3, 1, fence);

  // =========================================================================
  // 2. MASSIVE TIMBER LEGS (Y: 3..10)
  // =========================================================================

  const legs = [
    { name: "FL", x0: 4, z0: 6, isFront: true, isLeft: true },
    { name: "FR", x0: 9, z0: 6, isFront: true, isLeft: false },
    { name: "BL", x0: 4, z0: 15, isFront: false, isLeft: true },
    { name: "BR", x0: 9, z0: 15, isFront: false, isLeft: false },
  ];

  for (const { x0, z0, isFront, isLeft } of legs) {
    const x1 = x0 + 1;
    const z1 = z0 + 1;

    // Hoof base (Y: 3)
    for (let x = x0; x <= x1; x++) {
      for (let z = z0; z <= z1; z++) {
        setBlock(x, 3, z, stripY);
      }
    }
    // Hoof flared stairs
    setBlock(x0, 3, z0 - 1, stairState("north", "bottom"));
    setBlock(x1, 3, z0 - 1, stairState("north", "bottom"));
    setBlock(x0, 3, z1 + 1, stairState("south", "bottom"));
    setBlock(x1, 3, z1 + 1, stairState("south", "bottom"));
    if (isLeft) {
      setBlock(x0 - 1, 3, z0, stairState("west", "bottom"));
      setBlock(x0 - 1, 3, z1, stairState("west", "bottom"));
    } else {
      setBlock(x1 + 1, 3, z0, stairState("east", "bottom"));
      setBlock(x1 + 1, 3, z1, stairState("east", "bottom"));
    }

    // Lower Column / Cannon Bone (Y: 4..6)
    for (let y = 4; y <= 6; y++) {
      for (let x = x0; x <= x1; x++) {
        for (let z = z0; z <= z1; z++) {
          setBlock(x, y, z, stripY);
        }
      }
    }

    // Articulated Knee / Hock Joints (Y: 7..8)
    if (isFront) {
      // Front knee bends forward (Z - 1)
      for (let x = x0; x <= x1; x++) {
        for (let z = z0; z <= z1; z++) {
          setBlock(x, 7, z, logY);
          setBlock(x, 8, z, stripY);
        }
        setBlock(x, 7, z0 - 1, stairState("north", "bottom"));
        setBlock(x, 8, z0 - 1, stairState("north", "top"));
      }
    } else {
      // Rear equine hock points backward (Z + 2)
      for (let x = x0; x <= x1; x++) {
        for (let z = z0; z <= z1; z++) {
          setBlock(x, 7, z, logY);
          setBlock(x, 8, z + 1, stripY);
        }
        setBlock(x, 7, z1 + 1, stairState("south", "bottom"));
        setBlock(x, 8, z1 + 1, stairState("south", "top"));
      }
    }

    // Upper Thigh / Shoulder integration (Y: 9..10)
    for (let y = 9; y <= 10; y++) {
      const zMin = isFront ? z0 - 1 : z0;
      const zMax = isFront ? z1 + 1 : z1 + 2;
      for (let x = x0; x <= x1; x++) {
        for (let z = zMin; z <= zMax; z++) {
          setBlock(x, y, z, plank);
        }
      }
    }

    // Diagonal timber brace into the chassis
    const innerX = isLeft ? x1 + 1 : x0 - 1;
    setBlock(innerX, 4, z0, fence);
    setBlock(innerX, 5, z0, fence);
  }

  // =========================================================================
  // 3. HOLLOW TORSO & BELLY (Y: 9..18, Z: 5..19, X: 3..11)
  // =========================================================================

  for (let y = 9; y <= 18; y++) {
    for (let z = 5; z <= 19; z++) {
      const zRel = (z - 12.0) / 6.8;
      if (Math.abs(zRel) > 1.05) continue;

      const profile = Math.sqrt(Math.max(0, 1.0 - zRel * zRel * 0.88));
      const rx = 3.9 * profile + 0.35;

      let centerY = 13.5;
      if (z <= 8) {
        centerY = 14.1 + (8 - z) * 0.45; // Withers height
      } else if (z >= 16) {
        centerY = 13.9 + (z - 16) * 0.25; // Croup / Rump
      } else {
        centerY = 13.3 - Math.sin(((z - 8) / 8) * Math.PI) * 0.55; // Belly sag
      }

      const ry = (z <= 9 ? 4.5 : 4.1) * profile + 0.35;

      for (let x = 2; x <= 12; x++) {
        const dx = (x - 7.0) / rx;
        const dy = (y - centerY) / ry;
        const dist = dx * dx + dy * dy;

        if (dist <= 1.05) {
          const isRib = z === 5 || z === 8 || z === 12 || z === 15 || z === 19;
          const isSpine = Math.abs(x - 7) <= 0.7 && y >= centerY + ry - 1.2;
          const isKeel = Math.abs(x - 7) <= 0.7 && y <= centerY - ry + 1.2;

          let block = plank;
          if (isSpine || isKeel) block = stripZ;
          else if (isRib) block = logY;
          else if ((x + y + z) % 4 === 0) block = stripZ;

          setBlock(x, y, z, block);
        }
      }
    }
  }

  // Hollow out soldier chamber interior (Rule 9: Minimum 3x3x3 interior)
  for (let x = 5; x <= 9; x++) {
    for (let y = 11; y <= 15; y++) {
      for (let z = 9; z <= 16; z++) {
        delBlock(x, y, z);
      }
    }
  }

  // Solid floor at Y=10 under interior
  for (let x = 5; x <= 9; x++) {
    for (let z = 9; z <= 16; z++) {
      setBlock(x, 10, z, plank);
    }
  }

  // Solid bulkheads enclosing the chamber
  for (let x = 5; x <= 9; x++) {
    for (let y = 11; y <= 15; y++) {
      setBlock(x, y, 8, plank);
      setBlock(x, y, 17, plank);
    }
  }

  // Secret Trapdoor & Ladder Deployment Hatch (x=7, z=12)
  setBlock(7, 10, 12, trapdoorState("north", "bottom", false));
  for (let y = 3; y <= 10; y++) {
    setBlock(7, y, 11, logY);
    if (y <= 9) {
      setBlock(7, y, 12, "minecraft:ladder[facing=south]");
    }
  }

  // Flank peepholes for warriors observing Troy
  setBlock(4, 13, 11, trapdoorState("east", "bottom", false));
  setBlock(10, 13, 11, trapdoorState("west", "bottom", false));
  setBlock(4, 13, 14, trapdoorState("east", "bottom", false));
  setBlock(10, 13, 14, trapdoorState("west", "bottom", false));

  // =========================================================================
  // 4. POWERFUL CHEST, NECK & MANE (Y: 14..23, Z: 2..8, X: 4..10)
  // =========================================================================

  // Bulging Wooden Breast at front (Z: 5..7, Y: 12..16)
  for (let y = 12; y <= 16; y++) {
    for (let x = 5; x <= 9; x++) {
      setBlock(x, y, 5, plank);
      setBlock(x, y, 6, logZ);
    }
    setBlock(7, y, 4, stairState("north", "bottom"));
    setBlock(6, y, 4, stairState("north", "bottom"));
    setBlock(8, y, 4, stairState("north", "bottom"));
  }

  // Neck trajectory rising from chest/withers forward toward head
  const neckProfile = [
    { y: 15, cz: 6.8, wx: 2.2, wz: 2.2 },
    { y: 16, cz: 6.2, wx: 2.0, wz: 2.0 },
    { y: 17, cz: 5.5, wx: 1.8, wz: 1.9 },
    { y: 18, cz: 4.8, wx: 1.7, wz: 1.8 },
    { y: 19, cz: 4.2, wx: 1.6, wz: 1.7 },
    { y: 20, cz: 3.7, wx: 1.5, wz: 1.6 },
    { y: 21, cz: 3.3, wx: 1.4, wz: 1.5 },
    { y: 22, cz: 3.0, wx: 1.3, wz: 1.4 },
  ];

  for (const { y, cz, wx, wz } of neckProfile) {
    const xMin = Math.floor(7 - wx);
    const xMax = Math.ceil(7 + wx);
    const zMin = Math.floor(cz - wz);
    const zMax = Math.ceil(cz + wz);

    for (let x = xMin; x <= xMax; x++) {
      for (let z = zMin; z <= zMax; z++) {
        const dx = (x - 7.0) / wx;
        const dz = (z - cz) / wz;
        if (dx * dx + dz * dz <= 1.05) {
          const isEdge = dx * dx + dz * dz > 0.55;
          setBlock(x, y, z, isEdge ? plank : stripY);
        }
      }
    }

    // Carved Timber Mane along crest (+Z spine of neck)
    const maneZ = Math.round(cz + wz);
    setBlock(7, y, maneZ, stripZ);
    setBlock(7, y + 1, maneZ, stairState("north", "bottom"));
    setBlock(6, y, maneZ, stairState("west", "bottom"));
    setBlock(8, y, maneZ, stairState("east", "bottom"));
  }

  // =========================================================================
  // 5. HEAD, MUZZLE, EARS & BRIDLE (Y: 19..25, Z: 0..6, X: 4..10)
  // =========================================================================

  // Cranium & Jowls (Y: 20..23, Z: 2..5)
  for (let y = 20; y <= 23; y++) {
    for (let z = 2; z <= 5; z++) {
      for (let x = 5; x <= 9; x++) {
        setBlock(x, y, z, plank);
      }
    }
  }

  // Cheeks / Jowls shaping
  setBlock(4, 21, 3, stairState("east", "top"));
  setBlock(4, 21, 4, stairState("east", "top"));
  setBlock(10, 21, 3, stairState("west", "top"));
  setBlock(10, 21, 4, stairState("west", "top"));

  // Forehead Crown (Y: 24, Z: 3..4)
  setBlock(6, 24, 3, slabState("bottom"));
  setBlock(7, 24, 3, stripZ);
  setBlock(8, 24, 3, slabState("bottom"));
  setBlock(7, 24, 4, stairState("south", "bottom"));

  // Ears (Y: 24..25, X: 5 & 9, Z: 4)
  setBlock(5, 24, 4, stairState("north", "bottom"));
  setBlock(5, 25, 4, fence);
  setBlock(9, 24, 4, stairState("north", "bottom"));
  setBlock(9, 25, 4, fence);

  // Upper Snout & Bridge of Nose (Y: 21..22, Z: 1..2, X: 6..8)
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 22, 2, stripZ);
    setBlock(x, 22, 1, stairState("south", "bottom"));
    setBlock(x, 21, 1, plank);
  }

  // Nostrils & Muzzle Front (Z: 0..1, Y: 21)
  setBlock(6, 21, 0, stairState("south", "top"));
  setBlock(7, 21, 0, stripZ);
  setBlock(8, 21, 0, stairState("south", "top"));

  // Lower Jaw & Open Mouth (Y: 19..20, Z: 1..3, X: 6..8)
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 19, 2, stairState("north", "bottom"));
    setBlock(x, 19, 3, plank);
    setBlock(x, 20, 1, slabState("bottom"));
  }
  setBlock(7, 19, 1, stairState("north", "bottom"));

  // Eyes & Bridle Detailing
  setBlock(4, 22, 3, stairState("north", "top"));
  setBlock(10, 22, 3, stairState("north", "top"));
  setBlock(4, 21, 2, fence);
  setBlock(10, 21, 2, fence);
  setBlock(5, 20, 1, fence);
  setBlock(9, 20, 1, fence);

  // =========================================================================
  // 6. STYLIZED TIMBER TAIL (Y: 7..17, Z: 18..23, X: 5..9)
  // =========================================================================

  // Dock of tail emerging from rump
  setBlock(7, 16, 19, logZ);
  setBlock(7, 16, 20, stairState("south", "top"));

  // Flowing tail sweep
  setBlock(7, 15, 20, logY);
  setBlock(7, 15, 21, stairState("south", "bottom"));

  setBlock(6, 14, 21, stairState("east", "bottom"));
  setBlock(7, 14, 21, logY);
  setBlock(8, 14, 21, stairState("west", "bottom"));

  setBlock(6, 13, 21, plank);
  setBlock(7, 13, 21, logY);
  setBlock(8, 13, 21, plank);
  setBlock(7, 13, 22, stairState("south", "bottom"));

  setBlock(6, 12, 21, stairState("east", "top"));
  setBlock(7, 12, 21, logY);
  setBlock(8, 12, 21, stairState("west", "top"));

  setBlock(7, 11, 21, logY);
  setBlock(7, 11, 20, plank);

  setBlock(7, 10, 21, stairState("north", "bottom"));
  setBlock(7, 10, 20, logY);

  setBlock(7, 9, 20, fence);
  setBlock(7, 8, 20, fence);
  setBlock(6, 9, 20, fence);
  setBlock(8, 9, 20, fence);

  // =========================================================================
  // 7. WRITE VOXELS TO WORLD
  // =========================================================================

  for (const [key, block] of grid.entries()) {
    const [x, y, z] = key.split(",").map(Number);
    api.set(x, y, z, block);
  }

  return {
    name: "trojan_horse",
    seatY: 0,
    anchors: {
      front: [7, 2, 0],
      door: [7, 2, 12],
    },
    interiors: [
      {
        min: [5, 11, 9],
        max: [9, 15, 16],
        kind: "quarters",
      },
    ],
  };
}

