export const envelope = [13, 9, 13];

export default function build(api) {
  const W = envelope[0];
  const H = envelope[1];
  const D = envelope[2];

  // Injected seeded PRNG
  const rng = () => api.random();

  // 3D Grid buffer for strict 6-connectivity & deterministic emission
  const grid = new Array(W).fill(null).map(() =>
    new Array(H).fill(null).map(() =>
      new Array(D).fill(null)
    )
  );

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  // Palette extraction & helpers
  function getBase(str) {
    if (!str) return "";
    return str.split("[")[0];
  }

  function withAxis(blockStr, axis) {
    const base = getBase(blockStr) || "minecraft:oak_log";
    return `${base}[axis=${axis}]`;
  }

  function withFacing(blockStr, facing, half = "bottom") {
    const base = getBase(blockStr) || "minecraft:oak_stairs";
    return `${base}[facing=${facing},half=${half},shape=straight]`;
  }

  function withSlab(blockStr, type = "bottom") {
    const base = getBase(blockStr) || "minecraft:oak_slab";
    return `${base}[type=${type}]`;
  }

  const g = api.theme.ground || {};
  const w = api.theme.wood || {};
  const s = api.theme.stone || {};

  const pal = {
    dirt: g.bank || g.scree || "minecraft:coarse_dirt",
    mud: g.pavement || "minecraft:packed_mud",
    gravel: g.scree || "minecraft:gravel",
    stonePlinth: g.plinth || s.primary || "minecraft:stone_bricks",
    stoneAccent: s.accent || s.primary || "minecraft:cobblestone",
    stoneWall: s.wall || "minecraft:cobblestone_wall",
    stoneSlab: s.slab || "minecraft:cobblestone_slab",
    stoneStairs: s.stairs || "minecraft:cobblestone_stairs",
    log: w.log || "minecraft:oak_log",
    strippedLog: w.stripped || w.log || "minecraft:stripped_oak_log",
    planks: w.planks || "minecraft:oak_planks",
    fence: w.fence || "minecraft:oak_fence",
    woodSlab: w.slab || "minecraft:oak_slab",
    woodStairs: w.stairs || "minecraft:oak_stairs",
    trapdoor: w.trapdoor || "minecraft:oak_trapdoor",
    canvas: "minecraft:white_wool",
    canvasTorn: "minecraft:light_gray_wool",
    canvasBrown: "minecraft:brown_wool",
    coldCampfire: "minecraft:campfire[lit=false]",
    ash: "minecraft:basalt",
    hay: "minecraft:hay_block[axis=y]"
  };

  // Shared geometry helpers
  function buildRafterX(x1, y1, x2, y2, z, block, underBlock) {
    const dx = Math.sign(x2 - x1);
    const dy = Math.sign(y2 - y1);
    let cx = x1;
    let cy = y1;
    set(cx, cy, z, block);
    while (cx !== x2 || cy !== y2) {
      if (cx !== x2) {
        cx += dx;
        set(cx, cy, z, underBlock || block);
      }
      if (cy !== y2) {
        cy += dy;
        set(cx, cy, z, block);
      }
    }
  }

  function fillBox(x1, y1, z1, x2, y2, z2, block) {
    const minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
    const minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
    const minZ = Math.min(z1, z2), maxZ = Math.max(z1, z2);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          set(x, y, z, block);
        }
      }
    }
  }

  // Build unified solid ground footing at y=0 and earth berms at y=1
  function buildCommonGround() {
    for (let x = 1; x <= 11; x++) {
      for (let z = 1; z <= 11; z++) {
        const dsq = (x - 6) * (x - 6) + (z - 6) * (z - 6);
        if (dsq <= 30) {
          const r = rng();
          const groundBlock = r < 0.45 ? pal.mud : (r < 0.75 ? pal.dirt : pal.gravel);
          set(x, 0, z, groundBlock);

          // Outer earthwork embankment ring
          if (dsq >= 16 && dsq <= 28) {
            const r2 = rng();
            if (r2 < 0.6) {
              set(x, 1, z, r2 < 0.3 ? pal.dirt : pal.mud);
            }
          }
        }
      }
    }
  }

  buildCommonGround();

  // Determine variant (6 distinct plugin types)
  const variant = ((api.instance.index !== undefined ? api.instance.index : 0) + Math.floor(rng() * 6)) % 6;

  if (variant === 0) {
    // -------------------------------------------------------------
    // VARIANT 0: Abandoned Command Pavilion (Strategion)
    // -------------------------------------------------------------
    // Raised mud-brick & timber dais
    for (let x = 3; x <= 9; x++) {
      for (let z = 3; z <= 9; z++) {
        set(x, 1, z, (x === 3 || x === 9 || z === 3 || z === 9) ? pal.stonePlinth : pal.mud);
      }
    }

    // Heavy corner posts
    const postCoords = [[3, 3], [3, 9], [9, 3], [9, 9]];
    for (const [px, pz] of postCoords) {
      for (let y = 1; y <= 4; y++) {
        set(px, y, pz, withAxis(pal.log, "y"));
      }
    }

    // Horizontal tie-beams at y=4
    for (let x = 3; x <= 9; x++) {
      set(x, 4, 3, withAxis(pal.log, "x"));
      set(x, 4, 6, withAxis(pal.log, "x"));
      set(x, 4, 9, withAxis(pal.log, "x"));
    }
    for (let z = 3; z <= 9; z++) {
      set(3, 4, z, withAxis(pal.log, "z"));
      set(9, 4, z, withAxis(pal.log, "z"));
    }

    // Central ridge beam at x=6, y=7
    for (let z = 3; z <= 9; z++) {
      set(6, 7, z, withAxis(pal.log, "z"));
    }

