  // ---------------------------------------------------------------
  // Enforce Single 6-Connected Solid Component & Minimum Constraints
  // ---------------------------------------------------------------
  function enforceConnectedSolid() {
    const visited = new Uint8Array(W * H * D);
    const idx = (x, y, z) => x + y * W + z * W * H;
    const components = [];

    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) {
        for (let z = 0; z < D; z++) {
          if (!grid[x][y][z] || visited[idx(x, y, z)]) continue;

          const comp = [];
          const queue = [[x, y, z]];
          visited[idx(x, y, z)] = 1;

          let head = 0;
          while (head < queue.length) {
            const [cx, cy, cz] = queue[head++];
            comp.push([cx, cy, cz]);

            const neighbors = [
              [cx + 1, cy, cz], [cx - 1, cy, cz],
              [cx, cy + 1, cz], [cx, cy - 1, cz],
              [cx, cy, cz + 1], [cx, cy, cz - 1]
            ];

            for (const [nx, ny, nz] of neighbors) {
              if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
                if (grid[nx][ny][nz] && !visited[idx(nx, ny, nz)]) {
                  visited[idx(nx, ny, nz)] = 1;
                  queue.push([nx, ny, nz]);
                }
              }
            }
          }
          components.push(comp);
        }
      }
    }

    if (components.length === 0) return;

    // Keep only the largest 6-connected component
    components.sort((a, b) => b.length - a.length);
    const largestSet = new Set(components[0].map(([x, y, z]) => idx(x, y, z)));

    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) {
        for (let z = 0; z < D; z++) {
          if (grid[x][y][z] && !largestSet.has(idx(x, y, z))) {
            grid[x][y][z] = null;
          }
        }
      }
    }
  }

  enforceConnectedSolid();

  // Deterministic emission to api
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "greek_siege_camp",
    seatY: 0,
    anchors: {
      front: [6, 1, 0]
    }
  };
